uint warp=simdgroup_index_in_threadgroup;
uint tid=thread_index_in_threadgroup;
uint row=threadgroup_position_in_grid.x*32+lane;
float best=INFINITY;
uint index=0;
for(uint part=warp;part<PARTS;part+=WARPS){
